export{ModalDatoAdicionalArticuloCtrl};function ModalDatoAdicionalArticuloCtrl($scope,$uibModalInstance,params){let{entity:entity,datosAdicionales:datosAdicionales}=params;if(console.log(entity),$scope.etiquetas=entity.etiquetas[0].etiquetas,$scope.articulo=entity,$scope.data=[{idArticulo:$scope.articulo.idArticulo,idEtiqueta:$scope.articulo.etiquetas[0].idEtiqueta,idInfoAdicional:0,adicionales:{}}],datosAdicionales.some(item=>item.idArticulo===$scope.articulo.idArticulo)){let dataInfo=datosAdicionales.filter(item=>item.idArticulo===$scope.articulo.idArticulo);$scope.etiquetas=Object.keys(angular.copy(dataInfo[0].adicionales)),$scope.data=[...dataInfo]}else $scope.etiquetas=entity.etiquetas[0].etiquetas;$scope.addColumn=function(){try{Swal.fire({title:"Ingrese el nombre de la columna",input:"text",inputAttributes:{autocapitalize:"off"},showCancelButton:!0,confirmButtonText:"Ingresar",cancelButtonText:"Cancelar",inputValidator:value=>value?$scope.etiquetas.some(item=>item===value.trim())?"El nombre de la columna proporcionada ya existe":void 0:"Ingrese el nombre de la columna",allowOutsideClick:!1}).then(result=>{result.isConfirmed&&($scope.etiquetas.push(result.value),$scope.$apply())})}catch(error){console.log(error)}},$scope.updateNameColumn=function(index,column){try{let columnOriginal=column;Swal.fire({title:"Modificar el nombre de la columna",input:"text",inputValue:column,inputAttributes:{autocapitalize:"off"},showCancelButton:!0,confirmButtonText:"Ingresar",cancelButtonText:"Cancelar",inputValidator:value=>value?$scope.etiquetas.some(item=>item===value.trim())?"El nombre de la columna proporcionada ya existe":void 0:"Ingrese el nombre de la columna",allowOutsideClick:!1}).then(result=>{result.isConfirmed&&($scope.etiquetas[index]=result.value,$scope.data=$scope.data.map(obj=>{for(let key in obj.adicionales)key===columnOriginal&&(console.log(obj),obj.adicionales[result.value]=obj.adicionales[key],delete obj.adicionales[key]);return obj}),$scope.$apply())})}catch(error){console.log(error)}},$scope.addRow=function(){$scope.data.length!==$scope.articulo.cantidad?$scope.data.push({idArticulo:$scope.articulo.idArticulo,idEtiqueta:$scope.articulo.etiquetas[0].idEtiqueta,idInfoAdicional:0,adicionales:{}}):Swal.fire({title:"Datos Adicionales",icon:"warning",html:`El número de datos adicionales proporcionados no debe exceder la cantidad de artículo: <b>${$scope.articulo.descripcion}</b>!`})},$scope.removeRow=function(row){try{Swal.fire({title:"Eliminar Dato Adicional",icon:"warning",html:"Esta seguro de eliminar este dato adicional?",showConfirmButton:!0,showCancelButton:!0,cancelButtonText:"No, cancelar",confirmButtonText:"Si, eliminar"}).then(result=>{if(result.isConfirmed){let index=$scope.data.indexOf(row);$scope.data.splice(index,1),$scope.$apply()}})}catch(error){console.log(error)}},$scope.removeColumn=function(row){let index=$scope.etiquetas.indexOf(row);$scope.etiquetas.splice(index,1);for(let item of $scope.data)item.adicionales.hasOwnProperty(row)&&delete item.adicionales[row]},$scope.save=function(){try{if(0===$scope.data.length)return void Swal.fire({title:"Datos Adicionales",icon:"warning",html:"Ingrese los datos adicionales del artículo!"});for(let data of $scope.etiquetas)for(let item of $scope.data){if(0===Object.keys(item.adicionales).length)return void Swal.fire({title:"Datos Adicionales",icon:"warning",html:"Ingrese todos campos!"});if([null,void 0,""].includes(item.adicionales[data]))return void Swal.fire({title:"Datos Adicionales",icon:"warning",html:"Ingrese todos campos!"})}console.log($scope.data),$uibModalInstance.close($scope.data)}catch(error){console.log(error)}},$scope.closeModal=function(){$uibModalInstance.close()}}ModalDatoAdicionalArticuloCtrl.$inject=["$scope","$uibModalInstance","params"];